  // This height is expanded only during an active drag gesture to provide room
  // for the feedback text. The default is the compact 14dp hairline.
  static const double _seekStripFeedbackHeight = 28.0;

  @override
  Widget build(BuildContext context) {
    final palette = Theme.of(context).extension<AppPalette>()!;
