        border: Border(top: BorderSide(color: palette.divider, width: 1)),
      ),
      child: SizedBox(
        height: transportHeight,
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: const [
            SizedBox(height: _seekStripHeight, child: _SeekStrip()),
