  final Color trackColor;
  final Color fillColor;
  final int? durationMs;
  final bool dragging;
  final Color textColor;

  String _formatMs(int ms) {
    final int totalSeconds = ms ~/ 1000;
    final int minutes = totalSeconds ~/ 60;
    final int seconds = totalSeconds % 60;
    return "${minutes}:${seconds.toString().padLeft(2, '0')}";
  }

  @override
  void paint(Canvas canvas, Size size) {
    // Bottom-aligned 1 dp track hairline plus a thicker 1.5 dp filled portion mirroring the progress hairline.
    final y = size.height - 1.0;
    canvas.drawLine(
      Offset(0, y),
      Offset(size.width, y),
      Paint()
        ..color = trackColor
        ..strokeWidth = 1
        ..style = PaintingStyle.stroke,
    );
    if (fraction > 0) {
      canvas.drawLine(
        Offset(0, y),
        Offset(size.width * fraction, y),
        Paint()
          ..color = fillColor
          ..strokeWidth = 1.5
          ..strokeCap = StrokeCap.square
          ..style = PaintingStyle.stroke,
      );
    }

    // Draw in-flight seek feedback as text when dragging
    if (dragging && durationMs != null && durationMs! > 0) {
      final t = (fraction * durationMs!).round();
      final label = _formatMs(t) + ' / ' + _formatMs(durationMs!) + ' (' + ((fraction * 100).round()).toString() + '%)';
